    # I3: una versión FROZEN y sus secciones y líneas no cambian nunca (también lo cuida el
    # servicio). Los borradores se editan y se pueden descartar.
    op.execute(
        """
        CREATE FUNCTION budget_frozen_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE
          v_status text;
        BEGIN
          IF TG_TABLE_NAME = 'budget_versions' THEN
            IF OLD.status = 'FROZEN' THEN
              RAISE EXCEPTION 'budget_versions: la versión % está congelada', OLD.version_no;
            END IF;
            RETURN COALESCE(NEW, OLD);
          END IF;
          SELECT status INTO v_status FROM budget_versions
          WHERE id = COALESCE(NEW.version_id, OLD.version_id);
          IF v_status = 'FROZEN' THEN
            RAISE EXCEPTION '%: la versión está congelada', TG_TABLE_NAME;
          END IF;
          RETURN COALESCE(NEW, OLD);
        END $$
        """
    )
    op.execute(
        "CREATE TRIGGER budget_versions_frozen BEFORE UPDATE OR DELETE ON budget_versions "
        "FOR EACH ROW EXECUTE FUNCTION budget_frozen_guard()"
    )
